pub(super) fn category(c:char)->u8 {
    let i=RANGES.partition_point(|r|r.0<=c as u32); RANGES[i-1].1
}
pub(super) fn whitespace(c:char)->bool {
    matches!(c as u32, 0x9|0xa|0xb|0xc|0xd|0x20|0x85|0xa0|0x1680|0x2000|0x2001|0x2002|0x2003|0x2004|0x2005|0x2006|0x2007|0x2008|0x2009|0x200a|0x2028|0x2029|0x202f|0x205f|0x3000)
}
